begin;
create or replace function public.work_records(p_user uuid,p_entity text) returns setof jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare actor uuid:=p_user;begin
 case p_entity
 when 'transfer_destinations' then return query select jsonb_build_object('id',l.id,'label',w.code||' / '||l.code||' · '||l.name,'name',l.name,'warehouse_id',w.id,'state','active') from public.erp_locations l join public.erp_warehouses w on w.id=l.warehouse_id where l.active and w.active;
 when 'warehouses' then return query select to_jsonb(w)||jsonb_build_object('label',w.code||' · '||w.name,'state',case when w.active then 'active' else 'inactive' end) body from public.erp_warehouses w where exists(select from public.users where id=actor and role in ('admin qc','administrator inbionusa')) or exists(select from public.erp_locations l where l.warehouse_id=w.id and public.work_location_allowed(actor,l.id));
 when 'locations' then return query select to_jsonb(l)||jsonb_build_object('label',w.code||' / '||l.code||' · '||l.name,'warehouse',w.name,'state',case when l.active then 'active' else 'inactive' end) body from public.erp_locations l join public.erp_warehouses w on w.id=l.warehouse_id where public.work_location_allowed(actor,l.id);
 when 'warehouse_access' then return query select jsonb_build_object('id',u.id,'label',u.nama_lengkap,'name',u.nama_lengkap,'restricted',coalesce(s.restricted,false),'state',case when coalesce(s.restricted,false) then 'restricted' else 'all_warehouses' end,'warehouses',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('name',w.name)) from public.erp_warehouse_access a join public.erp_warehouses w on w.id=a.warehouse_id where a.user_id=u.id),'[]')) body from public.users u left join public.erp_warehouse_scopes s on s.user_id=u.id where u.is_active and exists(select from public.users where id=actor and role in ('admin qc','administrator inbionusa'));
 when 'formulas' then return query select to_jsonb(f)||jsonb_build_object('label',f.number||' · '||f.title||' / r'||f.revision,'product',p.nama_produk,'output_quantity',f.output_quantity::text,'unit',u.code) body from public.erp_formulas f join public.master_produk p on p.id=f.product_id join public.erp_units u on u.id=f.unit_id;
 when 'manufacturing_orders' then return query select (to_jsonb(m)-'batch_snapshot')||jsonb_build_object('label',m.number||' · '||p.nama_produk,'deviations',case when current_setting('work.detail',true) is distinct from 'false' then coalesce((select jsonb_agg(to_jsonb(d)||jsonb_build_object('approved_by_name',(select nama_lengkap from public.users where id=d.approved_by))) from public.erp_deviations d where d.manufacturing_order_id=m.id),'[]') else '[]'::jsonb end,'material_usage',case when current_setting('work.detail',true) is distinct from 'false' then coalesce((select jsonb_agg(req||jsonb_build_object('used_quantity',public.work_material_used(m.id,(req->>'material_id')::uuid)::text,'variance_quantity',(public.work_material_used(m.id,(req->>'material_id')::uuid)-(req->>'required_quantity')::numeric)::text)) from jsonb_array_elements(m.formula_snapshot->'requirements') req),'[]') else '[]'::jsonb end,'created_by_name',(select nama_lengkap from public.users where id=m.created_by),'approved_by_name',(select nama_lengkap from public.users where id=m.approved_by),'product',p.nama_produk,'unit',u.code,'location',l.name,'warehouse',w.name,'target_quantity',m.target_quantity::text,'scrap_quantity',m.scrap_quantity::text,'actual_quantity',coalesce((select sum(quantity) from public.erp_manufacturing_outputs where manufacturing_order_id=m.id),0)::text,'yield_percent',round(100*coalesce((select sum(quantity) from public.erp_manufacturing_outputs where manufacturing_order_id=m.id),0)/m.target_quantity,4)::text,'reservations',case when current_setting('work.detail',true) is distinct from 'false' then coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('quantity',r.quantity::text,'remaining',r.remaining::text,'lot',ml.number,'material',ma.name,'unit',um.code,'location',lo.name) order by r.created_at) from public.erp_material_reservations r join public.erp_material_lots ml on ml.id=r.lot_id join public.erp_materials ma on ma.id=ml.material_id join public.erp_units um on um.id=ma.unit_id join public.erp_locations lo on lo.id=r.location_id where r.manufacturing_order_id=m.id and public.work_location_allowed(actor,r.location_id)),'[]') else '[]'::jsonb end,'inputs',case when current_setting('work.detail',true) is distinct from 'false' then coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('quantity',i.quantity::text,'operator',(select nama_lengkap from public.users where id=i.measured_by),'location',(select name from public.erp_locations where id=i.location_id),'lot',ml.number,'material',ma.name,'unit',um.code) order by i.created_at) from public.erp_manufacturing_inputs i join public.erp_material_lots ml on ml.id=i.lot_id join public.erp_materials ma on ma.id=ml.material_id join public.erp_units um on um.id=ma.unit_id where i.manufacturing_order_id=m.id and public.work_location_allowed(actor,i.location_id)),'[]') else '[]'::jsonb end,'outputs',case when current_setting('work.detail',true) is distinct from 'false' then coalesce((select jsonb_agg(to_jsonb(o)||jsonb_build_object('quantity',o.quantity::text,'mfg_date',fl.mfg_date,'expiry_date',fl.expiry_date,'lot',fl.number,'quality_status',fl.qc_status) order by o.created_at) from public.erp_manufacturing_outputs o join public.erp_lots fl on fl.id=o.lot_id where o.manufacturing_order_id=m.id),'[]') else '[]'::jsonb end) body from public.erp_manufacturing_orders m join public.master_produk p on p.id=m.product_id join public.erp_units u on u.id=m.unit_id join public.erp_locations l on l.id=m.location_id join public.erp_warehouses w on w.id=l.warehouse_id where public.work_location_allowed(actor,m.location_id);
 when 'material_specs' then return query select to_jsonb(s)||jsonb_build_object('label',m.code||' · '||s.title||' / r'||s.revision,'material',m.name) body from public.erp_material_specs s join public.erp_materials m on m.id=s.material_id;
 when 'approved_suppliers' then return query select to_jsonb(a)||jsonb_build_object('label',m.code||' · '||s.name,'material',m.name,'supplier',s.name,'display_state',case when a.state='approved' and a.expiry_date<public.erp_today() then 'expired' else a.state end) body from public.erp_approved_suppliers a join public.erp_materials m on m.id=a.material_id join public.erp_suppliers s on s.id=a.supplier_id;
 when 'incoming_inspections' then return query select to_jsonb(i)||jsonb_build_object('label',i.number||' · '||m.name||' / '||l.number,'created_by_name',(select nama_lengkap from public.users where id=i.created_by),'approved_by_name',(select nama_lengkap from public.users where id=i.approved_by),'material',m.name,'lot',l.number,'supplier',s.name,'held',l.held) body from public.erp_incoming_inspections i join public.erp_material_lots l on l.id=i.lot_id join public.erp_materials m on m.id=l.material_id join public.erp_suppliers s on s.id=l.supplier_id where exists(select from public.erp_material_balances b where b.lot_id=l.id and public.work_location_allowed(actor,b.location_id));
 when 'controlled_documents' then return query select to_jsonb(d)||jsonb_build_object('label',d.number||' · '||d.title||' / r'||d.revision,'material',m.name,'supplier',s.name,'display_state',case when d.state='published' and d.expiry_date<public.erp_today() then 'expired' when d.state='published' and d.expiry_date<=public.erp_today()+30 then 'expiring' else d.state end) body from public.erp_controlled_documents d left join public.erp_materials m on m.id=d.material_id left join public.erp_suppliers s on s.id=d.supplier_id;
 when 'deviations' then return query select to_jsonb(d)||jsonb_build_object('label',d.number||' · '||d.title,'assignee_name',u.nama_lengkap,'material_lot',l.number,'production_order',m.number) body from public.erp_deviations d left join public.users u on u.id=d.assignee left join public.erp_material_lots l on l.id=d.material_lot_id left join public.erp_manufacturing_orders m on m.id=d.manufacturing_order_id where (d.inspection_id is null or exists(select from public.erp_incoming_inspections qi join public.erp_material_balances qb on qb.lot_id=qi.lot_id where qi.id=d.inspection_id and public.work_location_allowed(actor,qb.location_id))) and (d.material_lot_id is null or exists(select from public.erp_material_balances b where b.lot_id=d.material_lot_id and public.work_location_allowed(actor,b.location_id))) and (m.id is null or public.work_location_allowed(actor,m.location_id));
 when 'capas' then return query select to_jsonb(c)||jsonb_build_object('label',c.number||' · '||c.title,'deviation',d.number,'assignee_name',u.nama_lengkap) body from public.erp_capas c join public.erp_deviations d on d.id=c.deviation_id join public.users u on u.id=c.assignee where (d.inspection_id is null or exists(select from public.erp_incoming_inspections qi join public.erp_material_balances qb on qb.lot_id=qi.lot_id where qi.id=d.inspection_id and public.work_location_allowed(actor,qb.location_id))) and (d.material_lot_id is null or exists(select from public.erp_material_balances b where b.lot_id=d.material_lot_id and public.work_location_allowed(actor,b.location_id))) and (d.manufacturing_order_id is null or exists(select from public.erp_manufacturing_orders m where m.id=d.manufacturing_order_id and public.work_location_allowed(actor,m.location_id)));
 when 'warehouse_transfers' then return query select to_jsonb(t)||jsonb_build_object('label',t.number||' · '||f.code||' → '||dest.code,'source',f.name,'destination',dest.name,'lines',case when current_setting('work.detail',true) is distinct from 'false' then coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('quantity',x.quantity::text,'received',x.received::text,'lost',x.lost::text,'outstanding',(x.quantity-x.received-x.lost)::text,'lot',coalesce(ml.number,fl.number),'product',coalesce(mat.name,pr.nama_produk),'unit',u.code,'pallet',pal.number) order by x.id) from public.erp_transfer_lines x left join public.erp_material_lots ml on ml.id=x.material_lot_id left join public.erp_materials mat on mat.id=ml.material_id left join public.erp_lots fl on fl.id=x.lot_id left join public.master_produk pr on pr.id=fl.product_id left join public.erp_product_units pu on pu.product_id=pr.id and pu.is_base left join public.erp_units u on u.id=coalesce(mat.unit_id,pu.unit_id) left join public.erp_pallets pal on pal.id=x.pallet_id where x.transfer_id=t.id),'[]') else '[]'::jsonb end) body from public.erp_warehouse_transfers t join public.erp_locations f on f.id=t.from_location join public.erp_locations dest on dest.id=t.to_location where public.work_location_allowed(actor,t.from_location) or public.work_location_allowed(actor,t.to_location);
 when 'pallets' then return query select to_jsonb(p)||jsonb_build_object('label',p.number||' · '||coalesce(l.name,'In transit'),'location',l.name,'warehouse',w.name,'contents',case when current_setting('work.detail',true) is distinct from 'false' then coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('quantity',c.quantity::text,'lot',coalesce(ml.number,fl.number),'product',coalesce(mat.name,pr.nama_produk),'unit',u.code) order by c.id) from public.erp_pallet_contents c left join public.erp_material_lots ml on ml.id=c.material_lot_id left join public.erp_materials mat on mat.id=ml.material_id left join public.erp_lots fl on fl.id=c.lot_id left join public.master_produk pr on pr.id=fl.product_id left join public.erp_product_units pu on pu.product_id=pr.id and pu.is_base left join public.erp_units u on u.id=coalesce(mat.unit_id,pu.unit_id) where c.pallet_id=p.id),'[]') else '[]'::jsonb end) body from public.erp_pallets p left join public.erp_locations l on l.id=p.location_id left join public.erp_warehouses w on w.id=l.warehouse_id left join public.erp_warehouse_transfers t on t.id=p.transfer_id where public.work_location_allowed(actor,p.location_id) or (p.state='in_transit' and (public.work_location_allowed(actor,t.from_location) or public.work_location_allowed(actor,t.to_location)));
 when 'sample_requests' then return query select to_jsonb(s)||jsonb_build_object('label',s.number||' · '||c.name||' / '||p.nama_produk,'customer',c.name,'product',p.nama_produk,'unit',u.code,'quantity',s.quantity::text,'lot',l.number,'location',lo.name,'assignee_name',a.nama_lengkap,'quotation',q.number) body from public.erp_sample_requests s join public.erp_customers c on c.id=s.customer_id join public.master_produk p on p.id=s.product_id join public.erp_units u on u.id=s.unit_id left join public.erp_lots l on l.id=s.lot_id left join public.erp_locations lo on lo.id=s.location_id left join public.users a on a.id=s.assignee left join public.erp_quotes q on q.id=s.quote_id where s.location_id is null or public.work_location_allowed(actor,s.location_id);
 when 'customer_interactions' then return query select to_jsonb(i)||jsonb_build_object('label',c.name||' · '||i.subject,'customer',c.name,'assignee_name',a.nama_lengkap,'overdue',i.state='open' and i.due_date<public.erp_today()) body from public.erp_customer_interactions i join public.erp_customers c on c.id=i.customer_id left join public.users a on a.id=i.assignee;
 when 'document_distributions' then return query select to_jsonb(d)||jsonb_build_object('label',c.name||' · '||(d.document_snapshot->>'title'),'customer',c.name,'document',d.document_snapshot->>'number','revision',d.document_snapshot->>'revision','document_title',d.document_snapshot->>'title') body from public.erp_document_distributions d join public.erp_customers c on c.id=d.customer_id;
 when 'materials' then return query select to_jsonb(m)||jsonb_build_object('label',m.code||' · '||m.name,'unit',u.code,'state',case when m.active then 'active' else 'inactive' end) body from public.erp_materials m join public.erp_units u on u.id=m.unit_id;
 when 'suppliers' then return query select jsonb_build_object('id',s.id,'label',s.name,'name',s.name,'state',case when s.active then 'active' else 'inactive' end) body from public.erp_suppliers s;
 when 'products' then return query select jsonb_build_object('id',p.id,'label',p.kode_produk||' · '||p.nama_produk,'name',p.nama_produk,'unit_id',pu.unit_id,'unit',u.code,'state','active') body from public.master_produk p join public.erp_product_units pu on pu.product_id=p.id and pu.is_base join public.erp_units u on u.id=pu.unit_id;
 when 'units' then return query select to_jsonb(u)||jsonb_build_object('label',u.code||' · '||u.name) body from public.erp_units u;
 when 'staff' then return query select jsonb_build_object('id',u.id,'label',u.nama_lengkap,'name',u.nama_lengkap,'state','active') body from public.users u where u.is_active;
 when 'customers' then return query select jsonb_build_object('id',c.id,'label',c.name,'name',c.name,'contact',c.contact,'state','active') body from public.erp_customers c;
 when 'opportunities' then return query select jsonb_build_object('id',o.id,'label',o.number||' · '||o.company,'customer_id',o.customer_id,'state',o.stage) body from public.erp_opportunities o;
 when 'sales_orders' then return query select jsonb_build_object('id',o.id,'label',o.number||' · '||(o.snapshot->'customer'->>'name'),'state',o.state) body from public.erp_orders o;
 when 'product_documents' then return query select to_jsonb(d)||jsonb_build_object('label',d.number||' · '||d.title||' / r'||d.revision) body from public.erp_product_documents d;
 when 'deliveries' then return query select jsonb_build_object('id',m.id,'label',m.number||' · '||coalesce(m.snapshot->'customer'->>'name','Delivery'),'state',m.state,'version',m.version,'location_id',m.from_location,'lines',m.lines) body from public.erp_movements m where m.kind='delivery' and public.work_location_allowed(actor,m.from_location);
 when 'material_inventory' then return query select jsonb_build_object('id',l.id::text||':'||b.location_id::text,'lot_id',l.id,'material_id',m.id,'product_id',m.id,'label',m.name||' / '||l.number||' · '||lo.code,'product',m.name,'lot',l.number,'location_id',b.location_id,'location',lo.name,'warehouse',w.name,'on_hand',b.quantity::text,'reserved',(public.work_material_reserved(l.id,b.location_id))::text,'available',(case when public.work_material_eligible(l.id) then greatest(0,b.quantity-(public.work_material_reserved(l.id,b.location_id))) else 0 end)::text,'packed',public.work_packed('material',l.id,b.location_id)::text,'unit',u.code,'state',l.quality_status,'held',l.held,'expiry_date',l.expiry_date) body from public.erp_material_balances b join public.erp_material_lots l on l.id=b.lot_id join public.erp_materials m on m.id=l.material_id join public.erp_units u on u.id=m.unit_id join public.erp_locations lo on lo.id=b.location_id join public.erp_warehouses w on w.id=lo.warehouse_id where b.quantity>0 and public.work_location_allowed(actor,b.location_id);
 when 'material_lots' then return query select distinct jsonb_build_object('id',l.id,'label',m.name||' / '||l.number,'product',m.name,'material_id',m.id,'product_id',m.id,'unit',u.code,'state',l.quality_status,'held',l.held,'expiry_date',l.expiry_date) body from public.erp_material_balances b join public.erp_material_lots l on l.id=b.lot_id join public.erp_materials m on m.id=l.material_id join public.erp_units u on u.id=m.unit_id where public.work_location_allowed(actor,b.location_id);
 when 'finished_inventory' then return query select jsonb_build_object('id',l.id::text||':'||b.location_id::text,'lot_id',l.id,'material_id',m.id,'product_id',m.id,'label',m.nama_produk||' / '||l.number||' · '||lo.code,'product',m.nama_produk,'lot',l.number,'location_id',b.location_id,'location',lo.name,'warehouse',w.name,'on_hand',b.quantity::text,'reserved',(public.erp_reserved(l.id,b.location_id))::text,'available',(case when l.qc_status='released' and not l.held and l.expiry_date>=public.erp_today() then greatest(0,b.quantity-(public.erp_reserved(l.id,b.location_id))) else 0 end)::text,'packed',public.work_packed('finished',l.id,b.location_id)::text,'unit',u.code,'state',l.qc_status,'held',l.held,'expiry_date',l.expiry_date) body from public.erp_balances b join public.erp_lots l on l.id=b.lot_id join public.master_produk m on m.id=l.product_id join public.erp_product_units pu on pu.product_id=m.id and pu.is_base join public.erp_units u on u.id=pu.unit_id join public.erp_locations lo on lo.id=b.location_id join public.erp_warehouses w on w.id=lo.warehouse_id where b.quantity>0 and public.work_location_allowed(actor,b.location_id);
 when 'finished_lots' then return query select distinct jsonb_build_object('id',l.id,'label',m.nama_produk||' / '||l.number,'product',m.nama_produk,'material_id',m.id,'product_id',m.id,'unit',u.code,'state',l.qc_status,'held',l.held,'expiry_date',l.expiry_date) body from public.erp_balances b join public.erp_lots l on l.id=b.lot_id join public.master_produk m on m.id=l.product_id join public.erp_product_units pu on pu.product_id=m.id and pu.is_base join public.erp_units u on u.id=pu.unit_id where b.quantity>0 and public.work_location_allowed(actor,b.location_id);
 else raise check_violation;end case;end $$;
create or replace function public.work_read_guard(p_user uuid,p_entity text) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare scope text:=public.work_module(p_entity);begin
 if p_entity in ('material_lots','materials','staff') and exists(select from public.erp_modules where key in ('quality','production','purchase','crm','warehouse') and state<>'disabled' and public.erp_can(p_user,key,'read')) then return;end if;
 if p_entity in ('products','units','finished_lots') and exists(select from public.erp_modules where key in ('quality','production','sales','crm','warehouse') and state<>'disabled' and public.erp_can(p_user,key,'read')) then return;end if;
 if p_entity in ('suppliers') then scope:='purchase';if public.erp_can(p_user,'quality','read') then scope:='quality';end if;end if;
 if p_entity in ('customers','opportunities') then scope:='crm';end if;
 if p_entity='product_documents' then scope:='documents';end if;
 if p_entity='sales_orders' then scope:='sales';end if;
 if p_entity in ('deliveries','transfer_destinations') then scope:='warehouse';end if;
 if scope is null then raise insufficient_privilege;end if;
 perform public.erp_assert(p_user,scope,'read');
end $$;
create or replace function public.work_read_base(p_token text,p_entity text,p_query jsonb default '{}') returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare u public.users;source text;result jsonb;scope jsonb:=coalesce(p_query->'scope','{}');page_no integer:=coalesce((p_query->>'page')::integer,1);search_text text:=coalesce(p_query->>'search','');state_text text:=coalesce(p_query->>'state','');source_entity text;target text:=nullif(p_query->>'id','');begin
 u:=public.erp_actor(p_token);perform set_config('work.detail',case when target is null then 'false' else 'true' end,true);
 if length(p_query::text)>12000 or page_no not between 1 and 1000000 or length(search_text)>100 or length(state_text)>40 or jsonb_typeof(scope)<>'object' or exists(select from jsonb_each(scope) where key not in ('material_id','supplier_id','product_id','customer_id','location_id','warehouse_id','state','manufacturing_order_id')) then raise check_violation;end if;
 if p_entity='history' then
  source_entity:=p_query->>'source';perform public.work_read_guard(u.id,source_entity);
  if not exists(select from public.work_records(u.id,source_entity) r where r->>'id'=target) then raise insufficient_privilege;end if;
  source:=format('select to_jsonb(e)||jsonb_build_object(''before_data'',e.before_data-''batch_snapshot'',''after_data'',e.after_data-''batch_snapshot'',''actor'',a.nama_lengkap,''label'',e.action,''sort'',e.id::text) body from public.erp_work_events e join public.users a on a.id=e.actor_id where (e.entity=%L and e.record_id=%L::uuid) or e.after_data->>''manufacturing_order_id''=%L or e.after_data->>''transfer_id''=%L or e.after_data->>''pallet_id''=%L or e.before_data->>''manufacturing_order_id''=%L or e.before_data->>''transfer_id''=%L or e.before_data->>''pallet_id''=%L',source_entity,target,target,target,target,target,target,target);target:=null;
 elsif p_entity='genealogy' then
  if not (public.erp_can(u.id,'production','read') or public.erp_can(u.id,'warehouse','read') or public.erp_can(u.id,'quality','read')) then raise insufficient_privilege;end if;
  perform public.erp_assert(u.id,case when public.erp_can(u.id,'production','read') then 'production' when public.erp_can(u.id,'quality','read') then 'quality' else 'warehouse' end,'read');
  source:=format('select r body from public.work_genealogy(%L::uuid,%L::uuid) r',u.id,target);target:=null;
 else
  perform public.work_read_guard(u.id,p_entity);
  source:=format('select r body from public.work_records(%L::uuid,%L) r where not exists(select from jsonb_each_text(%L::jsonb) f where coalesce(r->>f.key,'''')<>f.value)',u.id,p_entity,scope::text);
 end if;
 perform set_config('app.table_query',coalesce(p_query->'grid','{}')::text,true);
 result:=public.erp_table_source(source,p_entity,search_text,state_text,page_no,target,'body');
 perform set_config('app.table_query','',true);
 return result;
end $$;
create or replace function public.erp_work_mutate(p_token text,p_action text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare u public.users;request uuid:=(p_payload->>'request_key')::uuid;prior public.erp_work_requests;result jsonb;begin
 perform pg_advisory_xact_lock(49281041);u:=public.erp_actor(p_token);
 if request is null or length(p_payload::text)>262144 then raise check_violation;end if;
 select * into prior from public.erp_work_requests where request_key=request;
 if found then
  if prior.actor_id<>u.id or prior.action<>p_action or prior.payload<>p_payload then raise exception using errcode='P0001',message='This request identifier was already used for another operation. Reload and retry.';end if;return prior.result;
 end if;
 perform set_config('inb.actor',u.id::text,true);perform set_config('inb.action',p_action,true);perform set_config('inb.reason',coalesce(p_payload->>'reason',''),true);
 if p_action in ('save_material_spec','revise_material_spec','approve_material_spec','withdraw_material_spec','save_approved_supplier','approve_supplier','withdraw_supplier','create_incoming_inspection','retest_incoming_inspection','save_incoming_results','finalize_incoming_inspection','save_deviation','submit_deviation','approve_deviation','close_deviation','save_capa','submit_capa','verify_capa','save_controlled_document','revise_controlled_document','publish_controlled_document','withdraw_controlled_document','set_material_quality_policy') then
  result:=public.work_quality_command(u.id,p_action,p_payload);
 elsif p_action in ('save_formula','revise_formula','approve_formula','withdraw_formula','create_manufacturing_order','release_manufacturing_order','reserve_manufacturing_material','release_material_reservation','consume_material','return_manufacturing_material','record_manufacturing_output','complete_manufacturing_order','close_manufacturing_order','cancel_manufacturing_order') then
  result:=public.work_manufacturing_command(p_token,u.id,p_action,p_payload);
 elsif p_action in ('save_warehouse','set_warehouse_access','save_warehouse_location','create_warehouse_transfer','dispatch_warehouse_transfer','receive_warehouse_transfer','close_warehouse_transfer','cancel_warehouse_transfer','create_pallet','pack_pallet','unpack_pallet','repack_pallet','move_pallet','retire_pallet','dispatch_pallet_delivery') then
  result:=public.work_warehouse_command(p_token,u.id,p_action,p_payload);
 elsif p_action in ('create_sample_request','approve_sample','prepare_sample','ship_sample','record_sample_feedback','create_sample_quotation','cancel_sample','log_customer_interaction','complete_customer_interaction','distribute_product_document','acknowledge_document_distribution','retract_document_distribution') then
  result:=public.work_customer_command(p_token,u.id,p_action,p_payload);
 else raise exception using errcode='P0001',message='Unknown operational command.';end if;
 insert into public.erp_work_requests(request_key,actor_id,action,payload,result) values(request,u.id,p_action,p_payload,result);
 return result;
end $$;
revoke all on function public.work_records(uuid,text),public.work_read_guard(uuid,text),public.work_read_base(text,text,jsonb),public.erp_work_mutate(text,text,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.erp_work_mutate(text,text,jsonb) to service_role;
notify pgrst,'reload schema';
commit;
